use soroban_sdk::{contract, contractimpl, Env};

#[contractimpl]
impl Token {
    pub fn get_balance(env: Env) -> i128 {
        env.storage().instance().get(&"balance").unwrap_or(0)
    }
}

use soroban_sdk::{contract, contractimpl, symbol_short, Env};

#[contractimpl]
impl Token {
    pub fn get_balance(env: Env) -> i128 {
        env.storage().instance().get(&symbol_short!("balance")).unwrap_or(0)
    }
}

use soroban_sdk::{contract, contractimpl, Env};

#[contractimpl]
impl Config {
    pub fn set_value(env: Env, key: &str, val: i128) {
        env.storage().instance().set(&format!("cfg_{}", key), &val);
    }
}
